// Builds curriculum/lesson-mstar-worksheets.js from per-lesson MSTAR practice
// worksheets. The printable sheet lives at lessons/<id>/mstar-worksheet.html
// (generated by scripts/generate-mstar-worksheets.mjs); a page on disk is the
// evidence in both directions, so this map cannot drift from the generator —
// the same contract as generate-lesson-family-homework-map.mjs, and
// tools/validate-lesson-catalogues.mjs holds it.
import { existsSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const lessonsDir = join(root, "lessons");
const outFile = join(root, "curriculum", "lesson-mstar-worksheets.js");

const entries = readdirSync(lessonsDir)
  .filter((d) => /^\d+-\d+$/.test(d))
  .filter((d) => existsSync(join(lessonsDir, d, "mstar-worksheet.html")))
  .sort((a, b) => {
    const [au, al] = a.split("-").map(Number);
    const [bu, bl] = b.split("-").map(Number);
    return au - bu || al - bl;
  })
  .map((id) => [
    id,
    {
      text: "🎯 MSTAR Practice Worksheet",
      href: `/lessons/${id}/mstar-worksheet.html`,
      isPrintable: true,
    },
  ]);

const body = entries.map(([id, e]) => `  ${JSON.stringify(id)}: ${JSON.stringify(e)},`).join("\n");

writeFileSync(
  outFile,
  `// GENERATED by scripts/generate-lesson-mstar-worksheet-map.mjs — do not hand-edit.
// Printable MSTAR-style practice worksheet per lesson (student sheet; the
// teacher answer key is the gated sibling mstar-worksheet-answer-key.html).
window.LESSON_MSTAR_WORKSHEETS = {
${body}
};
`,
);

console.log(
  `Wrote ${entries.length} MSTAR worksheet entries to curriculum/lesson-mstar-worksheets.js`,
);
